# Generated by scripts/cask.sh in tyldra-org/chargectl; the release workflow
# updates it. Edit the script there, not this file.
cask "chargectl" do
  version "0.1.2"
  sha256 "57c96adad82728177c81ea504e8f36c76e7d6917e7f92e001fd12eb5ab244870"

  url "https://github.com/tyldra-org/chargectl/releases/download/v#{version}/Chargectl-#{version}.zip"
  name "Chargectl"
  desc "Battery charge limiter for Apple silicon MacBooks"
  homepage "https://github.com/tyldra-org/chargectl"

  livecheck do
    url :url
    strategy :github_latest
  end

  depends_on arch: :arm64
  depends_on macos: :golden_gate

  app "Chargectl.app"

  # Releases are signed ad hoc and not notarized, so Gatekeeper would refuse to
  # open a quarantined copy. The archive's checksum is pinned above.
  postflight_steps do
    run "/usr/bin/xattr",
        args:           ["-dr", "com.apple.quarantine", "{{appdir}}/Chargectl.app"],
        writable_paths: ["Chargectl.app"],
        writable_base:  :appdir
  end

  uninstall quit: "com.tyldra.chargectl"

  zap trash: [
    "/Library/Application Support/Chargectl",
    "~/Library/Application Support/com.tyldra.chargectl",
    "~/Library/Caches/com.tyldra.chargectl",
    "~/Library/HTTPStorages/com.tyldra.chargectl",
    "~/Library/HTTPStorages/com.tyldra.chargectl.binarycookies",
    "~/Library/Preferences/com.tyldra.chargectl.plist",
    "~/Library/Saved Application State/com.tyldra.chargectl.savedState",
  ]

  caveats <<~EOS
    Open Chargectl from Applications to install its helper and choose a limit.
    To hand charging back to macOS before removing it, use
    Settings > Uninstall Chargectl, or run:
      brew uninstall --zap --cask chargectl
  EOS
end
